// Generates config/regions/index.generated.ts from every *.json pack in
// config/regions. Runs automatically before dev, build and test, so adding a
// region only needs a new JSON file.
import { readdirSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const dir = join(dirname(fileURLToPath(import.meta.url)), "..", "config", "regions");
const files = readdirSync(dir)
  .filter((f) => f.endsWith(".json"))
  .sort();

const lines = [
  "// AUTO-GENERATED by scripts/gen-regions.mjs. Do not edit; add a JSON file instead.",
  ...files.map((f, i) => `import p${i} from "./${f}";`),
  "",
  `export const rawRegionPacks: unknown[] = [${files.map((_, i) => `p${i}`).join(", ")}];`,
  "",
];
writeFileSync(join(dir, "index.generated.ts"), lines.join("\n"));
console.log(`gen-regions: ${files.length} packs`);
